package dev.termestra.workspace.adapter.in.http.filesystem;
import dev.termestra.workspace.application.port.in.browse.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import reactor.core.publisher.Mono;import reactor.core.scheduler.Schedulers;import java.util.*;
@RestController public final class FilesystemController {private final FilesystemBrowseUseCase filesystem;private final FilesystemPickerUseCase picker;public FilesystemController(FilesystemBrowseUseCase filesystem,FilesystemPickerUseCase picker){this.filesystem=filesystem;this.picker=picker;}
 @GetMapping("/api/fs/browse") Mono<ResponseEntity<Map<String,Object>>> browse(@RequestParam(required=false)String path){return Mono.fromCallable(()->{BrowseView value=filesystem.browse(path);Map<String,Object> result=new LinkedHashMap<>();result.put("current_path",value.currentPath());result.put("entries",value.entries().stream().map(FilesystemController::entry).toList());result.put("error",value.error());result.put("ok",value.ok());result.put("parent_path",value.parentPath());result.put("root_path",value.rootPath());result.put("truncated",value.truncated());return ResponseEntity.status(value.ok()?HttpStatus.OK:HttpStatus.BAD_REQUEST).body(result);}).subscribeOn(Schedulers.boundedElastic());}
 @GetMapping("/api/fs/probe") Mono<Map<String,Object>> probe(@RequestParam(required=false)String path){return Mono.fromCallable(()->{ProbeView value=filesystem.probe(path);Map<String,Object> result=new LinkedHashMap<>();result.put("current_branch",value.currentBranch());result.put("exists",value.exists());result.put("git_inspection_token",value.gitInspectionToken());result.put("is_dir",value.directory());result.put("is_git_repository",value.gitRepository());result.put("ok",value.ok());result.put("path",value.path());result.put("suggested_name",value.suggestedName());return result;}).subscribeOn(Schedulers.boundedElastic());}
 @PostMapping("/api/fs/pick-folder") Mono<Map<String,Object>> pickFolder(){return Mono.fromCallable(()->{PickFolderView value=picker.pick();Map<String,Object> result=new LinkedHashMap<>();result.put("canceled",value.canceled());result.put("error",value.error());result.put("path",value.path());result.put("probe",value.probe()==null?null:probe(value.probe()));result.put("supported",value.supported());return result;}).subscribeOn(Schedulers.boundedElastic());}
 private static Map<String,Object> probe(ProbeView value){Map<String,Object> result=new LinkedHashMap<>();result.put("current_branch",value.currentBranch());result.put("exists",value.exists());result.put("git_inspection_token",value.gitInspectionToken());result.put("is_dir",value.directory());result.put("is_git_repository",value.gitRepository());result.put("ok",value.ok());result.put("path",value.path());result.put("suggested_name",value.suggestedName());return result;}
 private static Map<String,Object> entry(BrowseEntryView value){return Map.of("is_dir",value.directory(),"is_git_repository",value.gitRepository(),"name",value.name(),"path",value.path());}}
